<script setup>
import { ref } from 'vue'; import { ArrowRight, LockKeyhole } from 'lucide-vue-next'; import { RouterLink, useRoute, useRouter } from 'vue-router'; import { useAuthStore } from '../../stores/auth';
const auth = useAuthStore(); const router = useRouter(); const route = useRoute(); const form = ref({ email: '', password: '' }); const error = ref('');
async function submit() { error.value = ''; try { await auth.login(form.value); router.push(route.query.redirect || '/'); } catch (e) { error.value = e.response?.data?.errors?.email?.[0] || e.response?.data?.message || 'The email or password was not recognised.'; } }
</script>
<template><section class="auth-page"><div class="auth-panel"><div class="auth-icon"><LockKeyhole :size="20" /></div><p class="kicker">WELCOME BACK</p><h1>Sign in to Nexus.</h1><p class="auth-intro">Your next setup is waiting.</p><form @submit.prevent="submit"><label class="field-label">Email<input v-model="form.email" type="email" required autocomplete="email"></label><label class="field-label">Password<input v-model="form.password" type="password" required autocomplete="current-password"></label><p v-if="error" class="form-error">{{ error }}</p><button class="button button-dark full-button" :disabled="auth.loading">{{ auth.loading ? 'Signing in...' : 'Sign in' }} <ArrowRight :size="16" /></button></form><p class="auth-switch">New here? <RouterLink to="/register">Create an account</RouterLink></p></div></section></template>
